[CmdletBinding()]param([Parameter(Mandatory)][string]$PackageRoot)
$source=Split-Path $PSCommandPath;$dest=Join-Path $PackageRoot 'm365-sharepoint-modernizer';$bin=Join-Path $env:ProgramFiles 'System8\bin';New-Item -ItemType Directory -Path $dest,$bin -Force|Out-Null;Copy-Item (Join-Path $source '*') $dest -Recurse -Force;Copy-Item (Join-Path (Split-Path $source) '_shared\S8.M365.psm1') $dest -Force
"@echo off`r`nwhere pwsh.exe >nul 2>&1`r`nif %errorlevel%==0 (pwsh.exe -NoProfile -ExecutionPolicy Bypass -File `"%ProgramData%\System8\Packages\m365-sharepoint-modernizer\sharepoint-modernizer.ps1`" %*) else (powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"%ProgramData%\System8\Packages\m365-sharepoint-modernizer\sharepoint-modernizer.ps1`" %*)"|Set-Content (Join-Path $bin 's8spmodern.cmd') -Encoding ASCII;Write-Host 'Installed command: s8spmodern' -ForegroundColor Green
